{"content":""""Isolierter Browser-Worker: nur SSRF-geprüfte URLs, ohne Secrets."""
from app.tools.registry import ssrf_geprueft
def abrufen(url: str) -> str:
    if not ssrf_geprueft(url): raise ValueError("URL blockiert (SSRF-Schutz)")
    return f"[Platzhalter] Abruf von {url} erfolgt isoliert und protokolliert."
","path":"workers/browser/worker.py"}

{"content":""""Isolierter Coding-Worker: separater Workspace, nur mit Freigabe."""
def vorschlag_erstellen(repo: str, beschreibung: str, freigegeben: bool) -> str:
    if not freigegeben: raise PermissionError("Coding-Eingriffe brauchen Freigabe")
    return f"[Platzhalter] Änderungsbericht für {repo}: {beschreibung}"
