@app.post("/api/v1/finance/import")
async def finance_import(datei: UploadFile = File(...), db: Session = Depends(get_db), _: str = Depends(aktuell)):
    import csv, io
    from datetime import datetime
    if not (datei.filename or "").lower().endswith(".csv"):
        raise HTTPException(400, "Nur CSV-Dateien (Spalten: datum, vermoegen, notiz).")
    roh = await datei.read()
    if len(roh) > 2 * 1024 * 1024: raise HTTPException(400, "CSV zu groß (max. 2 MB).")
    angelegt = 0
    for zeile in csv.DictReader(io.StringIO(roh.decode("utf-8", errors="replace"))):
        try:
            s = models.FinancialSnapshot(
                datum=datetime.fromisoformat(str(zeile.get("datum", ""))),
                vermoegen=float(str(zeile.get("vermoegen", "0")).replace(",", ".") if False else float(str(zeile.get("vermoegen", "0")).replace(".", "").replace(",", ".")) if "," in str(zeile.get("vermoegen", "0")) else float(str(zeile.get("vermoegen", "0"))),
                notiz=str(zeile.get("notiz", ""))[:200])
            db.add(s); angelegt += 1
        except (ValueError, KeyError): continue  # fehlerhafte Zeilen überspringen, Rest zählt
    db.add(models.Event(type="finance.snapshot_imported", source="api", ref_id="csv",
                        payload={"zeilen": angelegt}))
    db.commit(); return {"snapshots": angelegt}"}

