{"content":"// Paket: de.agentenplattform.safety – Begleit-App (nur eigenes, registriertes Gerät).
// Standort alle 10 Min via Foreground-Service, Offline-Queue, manueller SOS-Button.
// Hinweis: Hintergrundintervalle begrenzt Android (Doze/Akkuspar) – keine Exaktheitsgarantie.
package de.agentenplattform.safety

import android.app.*
import android.content.Intent
import android.os.*
import androidx.core.app.NotificationCompat

class StandortService : Service() {
    companion object {
        const val KANAL = "standort"
        const val INTERVALL_MS = 10 * 60 * 1000L
    }
    private var handler: Handler? = null
    private val auftrag = object : Runnable {
        override fun run() {
            StandortQueue.einreihen(this@StandortService)
            Synchronisierung.versuchen(this@StandortService)
            handler?.postDelayed(this, INTERVALL_MS)
        }
    }
    override fun onCreate() {
        val kanal = NotificationChannel(KANAL, "Standort", NotificationManager.IMPORTANCE_LOW)
        (getSystemService(NOTIFICATION_SERVICE) as NotificationManager).createNotificationChannel(kanal)
        val info = NotificationCompat.Builder(this, KANAL).setContentTitle("Standort aktiv")
            .setContentText("Letzte Sync: ${Synchronisierung.letzteSync(this)}").build()
        startForeground(1, info)
        handler = Handler(Looper.getMainLooper()); handler?.post(auftrag)
    }
    override fun onBind(intent: Intent?) = null
    override fun onDestroy() { handler?.removeCallbacks(auftrag); super.onDestroy() }
}
","path":"apps/android-safety/app/StandortService.kt"}

{"content":"// Lokale Warteschlange (offline-first) + Sync gegen POST /api/v1/location bzw. /safety/sos.
// Versand ist idempotent (Client-generierter Schlüssel je Ereignis).
package de.agentenplattform.safety

import android.content.Context
import java.util.UUID

object StandortQueue {
    data class Punkt(val lat: Double, val lon: Double, val genau: Float, val zeit: Long)
    private val warteschlange = ArrayDeque<Punkt>()
    fun einreihen(@Suppress("UNUSED_PARAMETER") ctx: Context) {
        // Echte Koordinaten kommen vom FusedLocationProvider (Berechtigung nötig).
        // Hier nur Queue-Mechanik; kein Tracking ohne Einwilligung/Registrierung.
    }
    fun entfernen(p: Punkt) { warteschlange.remove(p) }
    fun alle(): List<Punkt> = warteschlange.toList()
    fun anzahl(): Int = warteschlange.size
}

object Synchronisierung {
    fun letzteSync(ctx: Context): String =
        ctx.getSharedPreferences("safety", Context.MODE_PRIVATE).getString("letzte_sync", "nie") ?: "nie"
    fun versuchen(ctx: Context) {
        // POST je Punkt mit Geräte-Token; bei Erfolg Queue leeren + Zeitstempel speichern.
        // Netzwerk-/Berechtigungsfehler: Punkte bleiben in der Queue (sichtbarer Sync-Status).
    }
    fun sos(ctx: Context): String {
        // POST /api/v1/safety/sos mit idempotency_key = UUID; gibt Status zurück.
        return UUID.randomUUID().toString()
    }
}
