    return [{"id": c.id, "titel": c.titel, "beginn": str(c.beginn), "ende": str(c.ende), "fix": c.fix}
            for c in db.query(models.CalendarItem).order_by(models.CalendarItem.beginn.desc()).limit(200)]
@app.post("/api/v1/calendar")
def termin_anlegen(b: TerminNeu, db: Session = Depends(get_db), user: str = Depends(aktuell)):
    from datetime import datetime
    try: beginn, ende = datetime.fromisoformat(b.beginn), datetime.fromisoformat(b.ende)
    except ValueError: raise HTTPException(400, "ISO-Datum erwartet (z. B. 2026-11-02T09:00).")
    if ende <= beginn: raise HTTPException(400, "Ende muss nach Beginn liegen.")
    c = models.CalendarItem(titel=b.titel[:200], beginn=beginn, ende=ende, fix=b.fix)
    db.add(c); db.add(models.AuditLog(actor=user, aktion="calendar.create", detail=b.titel[:200])); db.commit()
    return {"id": c.id}
@app.delete("/api/v1/calendar/{cid}")
def termin_loeschen(cid: str, db: Session = Depends(get_db), user: str = Depends(aktuell)):
    c = db.query(models.CalendarItem).filter_by(id=cid).first()
    if c is None: raise HTTPException(404, "Termin unbekannt")
    db.delete(c); db.add(models.AuditLog(actor=user, aktion="calendar.delete", detail=cid)); db.commit()
    return {"geloescht": cid}

# --- Coding-Aufträge (Workspace, Freigabe-Pflicht) ---
class CodingBitte(BaseModel): beschreibung: str; patch: str = ""; approval_id: str | None = None
@app.post("/api/v1/coding/prepare")
def coding_prepare(b: CodingBitte, db: Session = Depends(get_db), user: str = Depends(aktuell)):
    from app.services.coding import auftrag_vorbereiten
    freigegeben = False
    if b.approval_id:
        a = db.query(models.Approval).filter_by(id=b.approval_id).first()
        freigegeben = bool(a and a.status == "genehmigt")
    ausgang = auftrag_vorbereiten(b.beschreibung, b.patch, freigegeben)
    db.add(models.AuditLog(actor=user, aktion="coding.prepare", detail=str(ausgang.get("status")))); db.commit()
    if ausgang.get("status") == "freigabe_noetig":
        ap = models.Approval(task_id="", zweck=f"Coding: {b.beschreibung[:200]}")
        db.add(ap); db.commit(); ausgang["approval_id"] = ap.id
    return ausgang

