@app.get("/api/v1/system/metrics")
def metrics_text(db: Session = Depends(get_db), _: str = Depends(aktuell)):
    from fastapi.responses import PlainTextResponse
    zeilen = ["# HELP aufgaben_status Anzahl Tasks je Status", "# TYPE aufgaben_status gauge"]
    pro: dict[str, int] = {}
    for t in db.query(models.Task).all(): pro[t.status] = pro.get(t.status, 0) + 1
